effect.shader:
void main(){
  vec2 uv = acScreenNorm;
  vec4 src = texture2DCv(inputImg.texture, uv);
  float a = max(src.a, 1e-4);
  vec3 c = src.rgb / a;
  float l = gmLum(c);
  l = clamp((l - 0.5) * contrast + 0.5 + brightness, 0.0, 1.0);
  l = pow(l, 1.0 / max(gamma, 0.05));
  vec3 col = mix(vec3(l), vec3(l) * tint.rgb, tintAmt);
  col = mix(c, col, mixAmt);
  gl_FragColor = vec4(col * a, a);
}
